mapper.select:
SELECT 'AD_GROUP' AS level, g.id, g.store_id, s.name AS store_name, s.currency, g.campaign_id, c.name AS campaign_name, c.tags AS campaign_tags, c.ad_type, g.id AS ad_group_id, g.name, g.status, g.platform_ad_group_id AS platform_id, g.default_bid AS bid, g.default_bid AS base_bid FROM ecom_ad_group g JOIN ecom_ad_campaign c ON c.id = g.campaign_id JOIN ecom_store s ON s.id = g.store_id WHERE 1 = 1 AND g.status <> 'ARCHIVED' AND c.status <> 'ARCHIVED'
AND g.store_id IN #{i}
AND g.campaign_id = #{campaignId} AND c.ad_type = #{adType} AND c.name LIKE CONCAT('%', #{keyword}, '%') ORDER BY g.store_id, c.name, g.name
